import assert from 'node:assert/strict';
import test from 'node:test';
import { readFileSync } from 'node:fs';
import * as taskModule from '../dist/graph/layout-task.js';
import { layoutGoldenFixtures, goldenPin } from './layout-golden-fixtures.mjs';

// Captured from the prior published numerical solver, not generated by the candidate under test.
const golden = JSON.parse(readFileSync(new URL('./fixtures/graph-layout-golden.json', import.meta.url), 'utf8'));
for (const fixture of layoutGoldenFixtures()) test(`committed layout outputs retain exact bytes: ${fixture.id}`, () => {
  const expected = golden.records.find(record => record.fixture === fixture.id);
  assert.ok(expected, 'every fixture has a retained reference');
  const factory = taskModule.createGraphIncrementalTaskKernel ?? taskModule.createGraphTaskKernel;
  const kernel = factory({ type: 'start', data: fixture.data }, { operationsPerStep: 7 });
  for (let frame = 0; frame < expected.outputs.length; frame++) {
    if (frame === 2) kernel.update({ type: 'pins', update: goldenPin(fixture.data.nodeCount) });
    if (frame === 4) kernel.update({ type: 'pins', update: goldenPin(0) });
    let actual;
    for (let calls = 0; calls < 2_000_000; calls++) {
      actual = kernel.step();
      if (actual.output !== undefined) break;
      assert.equal(actual.done, false);
    }
    assert.ok(actual?.output);
    const { positions, ...scalars } = actual.output;
    assert.deepEqual({ ...scalars, done: actual.done,
      positionsBase64: Buffer.from(positions.buffer, positions.byteOffset, positions.byteLength).toString('base64') }, expected.outputs[frame]);
  }
});
